          "editorMode": "code",
          "expr": "histogram_quantile(0.95, sum by (le) (rate(blocky_request_duration_seconds_bucket{job=~\"$job\", instance=~\"$instance\"}[$__rate_interval])))",
          "refId": "A",
          "range": true,
          "instant": false
        }
      ],
