      "options": {
        "inlineEditing": false,
        "showAdvancedTypes": false,
        "panZoom": false,
        "infinitePan": false,
        "root": {
          "type": "frame",
          "name": "Element 0",
          "background": {
            "color": {
              "fixed": "transparent"
            }
          },
          "border": {
            "color": {
              "fixed": "transparent"
            }
          },
          "constraint": {
